    // кнопка в отчёте разбора (app/app.js)
    'Работать в Studio': ['Studio-да жұмыс істеу', 'Work in Studio'], 'Сцены, кадры и промпты по этому сценарию': ['Осы сценарий бойынша сахналар, кадрлар және промпттар', 'Scenes, shots and prompts for this script'],
